/// <summary>What the kit needs to know about this product. Every value is read from the manifest.</summary>
public override ProductContract Contract { get; } = new(
    ModuleId: "{{ModuleId}}",
    ReadTool: "{{read_tool_name}}",          // a tool the approver may call without approval
    WriteTool: "{{write_tool_name}}",        // declared RequiresApproval = true
    // ApproverRole / NarrowRole default to system_admin / user; name product roles here when
    // the product's own roles are what should prove the gate (both must hold chat.use).
